INSERT INTO feature VALUES('formatter','printing','The source formatter',NULL,'implemented','ordinary',NULL,'`gandr fmt` lays a source out at a page width, keeping every token and comment and checking its meaning unchanged; each comment attached to the node it describes; `--form` and `@[ form(...) ]` rewrite between the sugared and the explicit spellings through a named rewrite table under the meaning check, a rewrite withdrawn visibly when it would change the meaning; the sugared form leaves a thunk type''s default grade `[ω]`, a tail return and the returner the lowering inserts at a definition''s result (`-> B` for `-> -F B`, an effect row kept) unwritten and writes a value-function alias at its shortest and a block''s linear runs at their reads, a match branch''s among them, a block left with no statement written as its one computation, checker-backed: a run is written away only where both spellings elaborate alike; a signature at a suspended returner or function and the thunk defining it, or the lambda the checker thunks, are written as one function form in either form, each binder of the lambda a parameter at its domain; any other signature and the definition directly after it, nothing but whitespace between them, are joined as `def x : T = e ;` in the sugared form and written apart in the explicit form; both one forms reach a module''s members, a nested module''s among them, as they reach top-level forms; the whole corpus is held to the sugared form.','surface-format surface-dispatcher','crates/surface-format/tests/format.rs crates/surface-format/tests/rewrite.rs corpus/model/basics/joined-definitions.gandr',NULL,NULL);
